// Wrong: the body binds straight to the entity, so any field can be rewritten
@PostMapping("/user")
public User updateUnsafe(@RequestBody User u) {
    return userRepo.save(u);
}

// Correct: a DTO containing only permitted fields
@PostMapping("/user/safe")
public User updateSafe(@RequestBody UpdateProfileDTO d) {
    User u = userRepo.findById(d.getId()).orElseThrow();
    u.setNickname(d.getNickname());
    return userRepo.save(u);
}

